css:
/* The staged rail translates its cards past the viewport, as the handoff does;
   the band clips them rather than letting the page scroll sideways. */
[data-bz-section="type-rail"] { overflow: hidden }
/* The rail sits on the darker chrome, as the header and footer do. */
/* The handoff's rail band is 96px over 88px inside a 48px gutter. */
[data-bz-section="type-rail"] > .bz-section { background: var(--chrome); padding-block: 96px 88px }
[data-bz-section="type-rail"] [data-bz-node="tr-head"] { padding-inline: var(--container-pad) }
[data-bz-section="type-rail"] > .bz-section { overflow: hidden }

/* The vehicle-type coverflow.
   --------------------------------------------------------------------------
   The handoff stages five cards around a centre one, each scaled and faded by
   its distance from the active index. No platform behaviour expresses that:
   `carousel` scrolls a rail, it does not transform slides, so this band
   carries its own script (see the js field) and the rules below.

   Everything up to .is-staged is the real, in-flow layout: that is what the
   Design canvas draws — it runs no site JS — what the first paint shows, and
   what a visitor without scripts gets. The script only switches it on. */

[data-bz-section="type-rail"] h2 { text-align: center; color: #fff; font-size: 32px; margin: 0 0 56px }

/* --- un-staged: a plain in-flow rail ------------------------------------- */
[data-bz-section="type-rail"] [data-bz-node="tr-rail"] {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 20px;
}
[data-bz-section="type-rail"] [data-bz-type="column"][data-bz-node^="tr-slide-"] {
  position: relative;
  flex: 0 1 240px;
  min-height: 420px;
  padding: 28px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
}

/* --- the card itself, either way ---------------------------------------- */
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-img"] { position: absolute; inset: 0; padding: 0 }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-img"] .bz-figure { margin: 0; height: 100% }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-img"] img { width: 100%; height: 100%; object-fit: cover }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-img"]::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(180deg, rgba(20,20,20,.25), rgba(20,20,20,.5));
}
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-h"],
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-cta"] { position: relative; z-index: 1; padding-block: 0 }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-h"] h3 {
  font-family: var(--font-heading); font-weight: 800; font-size: 15px;
  /* The handoff sets its card titles at the body leading, not the display one. */
  line-height: 1.6;
  color: #B5B5B5; text-align: center; padding: 0 20px; margin: 0;
}
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-cta"] { margin-top: auto }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-cta"] .bz-btns { justify-content: center; margin-block: 0 }
[data-bz-section="type-rail"] [data-bz-node^="tr-slide-cta"] .bz-btn {
  background: var(--accent); color: #fff; border-radius: 10px;
  font-weight: 700; font-size: 14px; min-height: 0; padding: 13px 26px; width: 150px;
}

/* --- arrows -------------------------------------------------------------- */
[data-bz-section="type-rail"] [data-bz-node="tr-nav"] { display: flex; justify-content: center; gap: 10px; margin-top: 24px }
[data-bz-section="type-rail"] [data-bz-node="tr-nav"] [data-bz-type="column"] { flex: 0 0 auto }
[data-bz-section="type-rail"] [data-bz-node="tr-nav"] .bz-btns { margin-block: 0 }
[data-bz-section="type-rail"] [data-bz-node="tr-nav"] .bz-btn {
  width: 40px; height: 40px; min-height: 0; padding: 0;
  border-radius: 50%; border: 1px solid #444; background: none; color: #fff;
  font-size: 16px; font-family: var(--font-body); font-weight: 400;
}
[data-bz-section="type-rail"] [data-bz-node="tr-nav"] .bz-btn:hover { background: rgba(255,255,255,.08) }

/* --- staged: the coverflow the handoff draws ----------------------------- */
[data-bz-section="type-rail"] [data-bz-node="tr-rail"].is-staged {
  display: block;
  position: relative;
  height: 460px;
  max-width: var(--container);
  margin: 0 auto;
}
[data-bz-section="type-rail"] .is-staged > [data-bz-type="column"][data-bz-node^="tr-slide-"] {
  position: absolute;
  top: 50%; left: 50%;
  width: 340px; height: 420px;
  margin-left: -170px; margin-top: -210px;
  flex: none;
  padding: 28px 0 0;
  justify-content: flex-start;
  gap: 10px;
  transition: transform .4s ease, opacity .4s ease;
  cursor: pointer;
}
[data-bz-section="type-rail"] .is-staged > [data-pos="0"]  { transform: translateX(0) scale(1);      opacity: 1;   z-index: 10; cursor: default }
[data-bz-section="type-rail"] .is-staged > [data-pos="-1"] { transform: translateX(-270px) scale(.78); opacity: .6;  z-index: 9 }
[data-bz-section="type-rail"] .is-staged > [data-pos="1"]  { transform: translateX(270px) scale(.78);  opacity: .6;  z-index: 9 }
[data-bz-section="type-rail"] .is-staged > [data-pos="-2"] { transform: translateX(-540px) scale(.6);  opacity: .32; z-index: 8 }
[data-bz-section="type-rail"] .is-staged > [data-pos="2"]  { transform: translateX(540px) scale(.6);   opacity: .32; z-index: 8 }
[data-bz-section="type-rail"] .is-staged > [data-pos="0"] [data-bz-node^="tr-slide-h"] h3 { font-size: 26px; color: #fff }
[data-bz-section="type-rail"] .is-staged > [data-pos="0"] [data-bz-node^="tr-slide-img"]::after {
  background: linear-gradient(180deg, rgba(20,20,20,.25), rgba(20,20,20,.72));
}
[data-bz-section="type-rail"] .is-staged > [data-bz-type="column"]:not([data-pos="0"]) [data-bz-node^="tr-slide-cta"] { display: none }
[data-bz-section="type-rail"] .is-staged > [data-pos="0"] [data-bz-node^="tr-slide-cta"] {
  position: absolute; bottom: 28px; left: 50%; transform: translateX(-50%); margin-top: 0;
}

@media (prefers-reduced-motion: reduce) {
  [data-bz-section="type-rail"] .is-staged > [data-bz-type="column"] { transition: none }
}

/* --- phone: the handoff's scroll-snap rail ------------------------------- */
@media (max-width: 640px) {
  [data-bz-section="type-rail"] h2 { font-size: 26px; padding: 0 20px; margin-bottom: 32px }
  [data-bz-section="type-rail"] [data-bz-node="tr-rail"],
  [data-bz-section="type-rail"] [data-bz-node="tr-rail"].is-staged {
    display: flex; position: static; height: auto; max-width: none;
    flex-wrap: nowrap; justify-content: flex-start;
    gap: 14px; overflow-x: auto; scroll-snap-type: x mandatory;
    padding: 0 20px;
  }
  [data-bz-section="type-rail"] [data-bz-type="column"][data-bz-node^="tr-slide-"],
  [data-bz-section="type-rail"] .is-staged > [data-bz-type="column"][data-bz-node^="tr-slide-"] {
    position: relative; top: auto; left: auto; margin: 0; transform: none; opacity: 1;
    flex: 0 0 200px; width: auto; height: 260px; min-height: 0;
    scroll-snap-align: start; justify-content: flex-end; padding: 16px;
  }
  [data-bz-section="type-rail"] [data-bz-node^="tr-slide-h"] h3 { font-size: 16px; color: #fff; text-align: left; padding: 0 }
  /* On a phone the handoff draws every card the same size — the staged
     centre card's 26px rule has to be answered at its own weight. */
  [data-bz-section="type-rail"] .is-staged > [data-pos="0"] [data-bz-node^="tr-slide-h"] h3 { font-size: 16px }
  [data-bz-section="type-rail"] .is-staged > [data-bz-type="column"] [data-bz-node^="tr-slide-cta"] { display: none }
  [data-bz-section="type-rail"] [data-bz-node="tr-nav"] { display: none }
}

js:
/* Stage the vehicle-type rail as the handoff's coverflow.
 *
 * The platform carousel behaviour scrolls a rail; it has no option that scales
 * and fades slides by their distance from an active index, which is what this
 * band is drawn as. So the markup stays a real in-flow rail — correct in the
 * Design canvas, in the first paint and with scripts off — and this adds the
 * staging on top. Scoped to this component's own nodes.
 */
(function () {
  document.querySelectorAll('[data-bz-section="type-rail"]').forEach(function (band) {
    var rail = band.querySelector('[data-bz-node="tr-rail"]');
    if (!rail) return;
    var slides = Array.prototype.filter.call(rail.children, function (el) {
      return (el.getAttribute('data-bz-node') || '').indexOf('tr-slide-') === 0;
    });
    if (slides.length < 2) return;

    var active = Math.floor(slides.length / 2);

    function place() {
      slides.forEach(function (slide, i) {
        var pos = i - active;
        slide.setAttribute('data-pos', String(pos));
        slide.setAttribute('aria-hidden', pos === 0 ? 'false' : 'true');
        // Only the centre card's link is reachable, so a keyboard user does not
        // tab into cards they cannot see.
        slide.querySelectorAll('a').forEach(function (a) {
          if (pos === 0) a.removeAttribute('tabindex');
          else a.setAttribute('tabindex', '-1');
        });
      });
    }

    function go(delta) {
      active = Math.min(slides.length - 1, Math.max(0, active + delta));
      place();
    }

    slides.forEach(function (slide, i) {
      slide.addEventListener('click', function (event) {
        if (i === active) return;
        event.preventDefault();
        active = i;
        place();
      });
    });

    function wire(nodeId, delta) {
      var host = band.querySelector('[data-bz-node="' + nodeId + '"]');
      if (!host) return;
      var control = host.querySelector('a, button');
      if (!control) return;
      control.addEventListener('click', function (event) {
        event.preventDefault();
        go(delta);
      });
    }
    wire('tr-prev', -1);
    wire('tr-next', 1);

    rail.classList.add('is-staged');
    place();
  });
})();
